"""Execute generated launchers with synthetic children/clients only. No sockets."""
import ctypes,hashlib,json,os,pathlib,re,signal,subprocess,sys,tempfile,time
ctypes.CDLL(None).prctl(36,1,0,0,0) # Linux child subreaper for fixture grandchildren.
launchers=json.load(sys.stdin)
results=[]
for variant,original in launchers.items():
 for mode in ('retry','reject','malformed','accepting','multiline','timeout','early7','during7','normal7','signal'):
  with tempfile.TemporaryDirectory(prefix='palworld-readiness-') as directory:
   root=pathlib.Path(directory); private=root/'.voltra'; private.mkdir()
   client=private/'console-client'
   client.write_text('''#!/bin/bash
set -eu
printf '%s\\n' "$*" >> calls
[ "${!#}" = Info ] || exit 0
n=0; [ ! -f count ] || n=$(cat count); n=$((n+1)); echo "$n" > count
case "$MODE" in
 reject) exit 1;;
 malformed) echo 'Unknown command'; exit 0;;
 accepting) exit 0;;
 multiline) printf 'Welcome to Pal Server[v1.0] Synthetic\\nextra\\n'; exit 0;;
 timeout) exec sleep 10;;
 early7) sleep .1; exit 1;;
 during7) sleep .15;;
 retry) [ "$n" -gt 1 ] || exit 1;;
esac
printf 'Welcome to Pal Server[v1.0.5.102999] Synthetic\\n'
'''); client.chmod(0o700)
   for name in ('palworld-console.json','console-client.manifest.json','console-client.LICENSE'):
    (private/name).write_text('{}')
   settings=root/('Pal/Saved/Config/WindowsServer/PalWorldSettings.ini' if variant.endswith('proton') else 'Pal/Saved/Config/LinuxServer/PalWorldSettings.ini')
   settings.parent.mkdir(parents=True);settings.write_text('synthetic')
   child=root/'child'; child.write_text('''#!/bin/bash
case "$MODE" in
 early7) exit 7;;
 during7) sleep .05; exit 7;;
 normal7) sleep .3; exit 7;;
 *) sleep .4;;
esac
''');child.chmod(0o700)
   # Replace only platform preflight/game invocation and absolute fixture root/hash.
   # Shared readiness, traps, stdin forwarding and waits remain generated bytes.
   s=original.replace('/home/container',directory)
   s=re.sub(r"(?<=printf '%s  %s\\n' ')[0-9a-f]{64}",hashlib.sha256(client.read_bytes()).hexdigest(),s)
   start=s.index('chmod 600 '); end=s.index('game_pid=$!')
   chmod=s[start:s.index('\n',start)]
   s=s[:start]+chmod+'\n./child &\n'+s[end:]
   s=s.replace('attempt<300','attempt<3').replace('sleep 1\n','sleep .02\n')
   s=s.replace('timeout --kill-after=1 3','timeout --kill-after=.1 .12')
   launcher=root/'launcher';launcher.write_text(s)
   p=subprocess.Popen(['/bin/bash',str(launcher)],cwd=root,env={**os.environ,'MODE':mode,'SERVER_PORT':'8211'},stdin=subprocess.PIPE,stdout=subprocess.PIPE,stderr=subprocess.PIPE,start_new_session=True)
   try:
    if mode=='signal': time.sleep(.15);os.kill(p.pid,signal.SIGTERM)
    out,err=p.communicate(b'',timeout=5)
    markers=out.count(b'VOLTRA_PALWORLD_CONSOLE_READY')
    expected=1 if mode in ('retry','normal7','signal') else 0
    assert markers==expected,(variant,mode,p.returncode,out,err)
    if mode in ('early7','during7','normal7'):assert p.returncode==7,(mode,p.returncode,err)
    if mode=='signal':assert p.returncode==143,(p.returncode,err)
    assert b'Welcome to Pal' not in out,(mode,out)
    calls=(root/'calls').read_text() if (root/'calls').exists() else ''
    assert 'password' not in calls
    results.append({'variant':variant,'case':mode,'exit':p.returncode,'markers':markers})
   finally:
    try:os.killpg(p.pid,signal.SIGKILL)
    except ProcessLookupError:pass
    p.wait()
    while True:
     try: os.waitpid(-1,0)
     except ChildProcessError: break
print(json.dumps({'generated_sha256':{k:hashlib.sha256(v.encode()).hexdigest() for k,v in launchers.items()},'results':results,'cleanup':'all fixture process groups killed and launcher children reaped; temporary directories removed'},indent=2))
